import numpy as np
import pandas as pd
from lxml import etree

def r_read_xml(x, encoding="", *args, as_html=False, options="NOBLANKS", **kwargs):
    """
    Python implementation of xml2::read_xml.

    R's xml2::read_xml returns an 'xml_document' object which, when serialized 
    or printed as text, includes the full XML declaration and DOCTYPE. 
    lxml.etree._Element only represents the root node. To match R's output, 
    we must return an lxml.etree._ElementTree object.
    """
    if not isinstance(x, str):
        x = str(x)

    # R's options "NOBLANKS" logic:
    # In lxml, remove_blank_text is handled by the parser.
    remove_blanks = True if options == "NOBLANKS" else False

    if "<" in x or ">" in x:
        # Treat as raw XML/HTML string
        content = x.encode('utf-8')
        if as_html:
            parser = etree.HTMLParser(remove_blank_text=remove_blanks)
            # etree.fromstring returns an Element; we need a Tree to preserve 
            # the full document context (DOCTYPE, etc.)
            # For HTML, lxml's HTMLParser usually wraps in <html><body>
            doc = etree.fromstring(content, parser=parser)
            return etree.ElementTree(doc)
        else:
            parser = etree.XMLParser(remove_blank_text=remove_blanks, resolve_entities=True)
            # Use XMLParser with resolve_entities=True to handle internal ENTITY definitions
            doc = etree.fromstring(content, parser=parser)
            return etree.ElementTree(doc)
    else:
        # Treat as a path or URL
        if as_html:
            parser = etree.HTMLParser(remove_blank_text=remove_blanks)
            return etree.parse(x, parser=parser)
        else:
            parser = etree.XMLParser(remove_blank_text=remove_blanks, resolve_entities=True)
            return etree.parse(x, parser=parser)
